/* Developer Portal — independent product entry. All records in this prototype are simulated. */
(function(){'use strict';
const C=window.PeachCore;
const UI_KEY='peach-media-developers-v1';
const panels={overview:['开发者概览','接入健康度、项目、凭证与外部调用'],projects:['应用与环境','每个业务应用管理自己的开发和生产环境'],credentials:['API 凭证','管理访问范围、密钥轮换与吊销'],webhooks:['Webhook 订阅','配置业务系统接收事件的地址'],docs:['集成指南','鉴权、上传、处理、Webhook 和安全实践'],sdk:['SDK 与示例','JavaScript、Python、Java 接入示例'],activity:['调用日志','最近 Open API 请求和业务事件'],usage:['接口用量','资源与事件的租户级调用趋势']};
const nav=[['overview','◈'],['projects','▣'],['credentials','⌘'],['webhooks','↗'],['docs','≡'],['sdk','{ }'],['activity','☷'],['usage','▥']];
const tenants=C.createSeed().tenants;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
let view='overview',tenantId='t1',live=false,connecting=true,credentials=[],activity={items:[],totalCalls:0,assets:[],jobs:[]},dialog=null,working=false;
let projects=[],webhooks=[];
try{const prev=JSON.parse(localStorage.getItem(UI_KEY)||'{}');if(tenants.some(x=>x.id===prev.tenantId))tenantId=prev.tenantId;projects=Array.isArray(prev.projects)?prev.projects:[];webhooks=Array.isArray(prev.webhooks)?prev.webhooks:[];}catch{}
function persist(){try{localStorage.setItem(UI_KEY,JSON.stringify({tenantId,projects,webhooks}));}catch{}}
const saveToast=(message)=>{const el=document.getElementById('dev-toast');if(!el)return;el.textContent=message;el.classList.add('visible');clearTimeout(saveToast.timer);saveToast.timer=setTimeout(()=>el.classList.remove('visible'),3800);};
const button=(label,action,cls='',attrs='')=>`<button type="button" class="portal-button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const box=(title,contents,cls='')=>`<section class="portal-card ${cls}"><h3>${title}</h3>${contents}</section>`;
const metric=(label,val,hint)=>`<div class="portal-card"><div class="label">${label}</div><div class="value">${val}</div><div class="hint">${hint}</div></div>`;
const code=s=>`<pre class="portal-code"><code>${esc(s)}</code></pre>`;
const status=()=>live?'<span class="pill">● 本地 Mock API 已连接</span>':'<span class="pill warn">○ 静态预览 · 需要本地 Mock 服务</span>';
const tenantName=()=>tenants.find(t=>t.id===tenantId)?.name||'未知租户';
function banner(){return `<div class="portal-alert info" style="margin-bottom:18px">此页面为 <strong>HTML 原型</strong>。项目和 Webhook 保存于浏览器；API Key 与外部调用活动在本地 Node 模拟服务中管理，非生产凭据或真实投递。${!live?'运行 <code>node prototype/mock-server.cjs</code> 可体验跨入口 API 联动。':''}</div>`;}
function dashboard(){return `${banner()}<div class="dev-hero"><div><span class="portal-eyebrow" style="color:#d2bfff">DEVELOPER WORKSPACE</span><h2>让每一次 API 调用，都能回到你的业务结果。</h2><p>在这里申请凭证、连接第三方应用、追踪上传与任务事件，再由企业控制台管理资产和用量。</p><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:17px"><a class="portal-button primary" href="../openapi/index.html">打开 API 调试器 ↗</a>${button('创建 API Key','open-key')}</div></div><span class="hero-glyph">{ }</span></div><div class="portal-grid four">${metric('已接入应用',fmt(allProjects().length),'按当前企业统计')}${metric('有效 API Key',fmt(credentials.filter(c=>c.status==='ACTIVE').length),'仅显示脱敏前缀')}${metric('累计 API 请求',fmt(activity.totalCalls),'本地模拟服务中的调用')}${metric('外部创建任务',fmt(activity.jobs?.length),'模拟服务创建的任务')}</div><div class="portal-grid two portal-panel">${box('最近 API 活动',activityTable(5))}${box('快速入门',`<div class="portal-list">${['创建接入项目并选择环境','申请最小权限的 API Key','调用 Upload API 上传文件','提交媒体处理任务并查询状态','配置 Webhook 并验证回调'].map((x,i)=>`<div class="portal-list-row"><span><b style="color:#645bd6;margin-right:9px">0${i+1}</b>${x}</span>${i===0?'→':''}</div>`).join('')}</div>`)}</div>`;}
function allProjects(){return [...C.onlyTenant(C.createSeed().projects,tenantId),...projects.filter(p=>p.tenantId===tenantId)];}
function projectPage(){return `${banner()}<div class="portal-toolbar"><span class="portal-alert success">每个应用的项目与环境，是 API Key 与资源配额的授权边界。</span>${button('＋ 创建接入应用','open-project','primary')}</div><div class="portal-grid">${allProjects().map(p=>`<article class="portal-card"><div class="label">APPLICATION / ${esc(p.env||'Production')}</div><h3 style="font-size:17px;margin:12px 0">${esc(p.name)}</h3><div class="portal-kpi-line"><span>项目编号</span><strong>${esc(p.id)}</strong></div><div class="portal-kpi-line"><span>环境</span><strong>${esc(p.env||'Production')}</strong></div><div style="margin-top:17px">${button('查看集成指南','goto-docs','sm')}</div></article>`).join('')}</div>`;}
function credentialPage(){return `${banner()}<div class="portal-toolbar"><span class="portal-inline">Secret 只在创建后展示一次；持久化时仅保存摘要与前缀。</span>${button('＋ 生成 API Key','open-key','primary',working?'disabled':'')}</div>${!live?'<div class="portal-alert">本地 API 未连接。当前不可创建、撤销真实可调用的演示 Key；启动 Node 模拟服务后重试。</div>':''}<div class="portal-card portal-panel"><div class="panel-head"><h3>项目凭证</h3>${button('刷新列表','refresh','sm')}</div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>名称</th><th>Key 前缀</th><th>权限范围</th><th>状态</th><th>操作</th></tr></thead><tbody>${credentials.map(k=>`<tr><td><b>${esc(k.name)}</b></td><td><code>${esc(k.prefix)}</code></td><td>${esc(k.scopes.join(', '))}</td><td><span class="pill ${k.status==='ACTIVE'?'':'muted'}">${k.status}</span></td><td>${!k.id.startsWith('demo_')&&k.status==='ACTIVE'?button('撤销','revoke-key','sm danger',`data-id="${esc(k.id)}"`):'<span class="portal-inline">系统样例</span>'}</td></tr>`).join('')||'<tr><td colspan="5">尚未创建凭证</td></tr>'}</tbody></table></div></div>`;}
function webhookPage(){return `${banner()}<div class="portal-toolbar"><span class="portal-inline">模拟订阅资产发布、处理成功与处理失败事件；演示不向外网发送请求。</span>${button('＋ 创建回调订阅','open-webhook','primary')}</div><div class="portal-grid two">${webhooks.filter(w=>w.tenantId===tenantId).map(w=>box(esc(w.name),`<div class="portal-kpi-line"><span>HTTPS 端点</span><strong style="word-break:break-word">${esc(w.url)}</strong></div><div class="portal-kpi-line"><span>事件类型</span><strong>${esc(w.type)}</strong></div><div class="portal-toolbar" style="margin-top:17px;margin-bottom:0"><span class="pill blue">本地模拟订阅</span>${button('发送测试事件','test-webhook','sm',`data-id="${esc(w.id)}"`)}</div>`)).join('')||box('尚无回调订阅','<p class="portal-inline">点击“创建回调订阅”录入一个测试 HTTPS 地址。</p>')}</div>`;}
function docsPage(){return `${banner()}<div class="portal-grid two">${box('API 基础约定',`<div class="portal-kpi-line"><span>Base URL</span><code>/openapi/v1</code></div><div class="portal-kpi-line"><span>鉴权</span><code>Authorization: Bearer &lt;api-key&gt;</code></div><div class="portal-kpi-line"><span>幂等</span><code>Idempotency-Key</code></div><div class="portal-kpi-line"><span>异步处理</span><code>202 Accepted + jobId</code></div><a class="portal-button primary" href="../openapi/index.html" style="margin-top:17px">打开交互式 API ↗</a>`)}${box('集成流程',`<div class="portal-list">${['租户与项目环境授权','生成 API Key（最小 Scope）','调用 Upload API 创建会话','文件上传 Complete 后处于隔离态','创建 Job 并轮询状态 / Webhook','资产正式发布与用量统计'].map((x,i)=>`<div class="portal-list-row"><span>${String(i+1).padStart(2,'0')} · ${x}</span></div>`).join('')}</div>`)}</div>`;}
function sdkPage(){const snippet=`// JavaScript (Node 18+) · demo only\nconst base = 'http://127.0.0.1:8080';\nconst response = await fetch(base + '/openapi/v1/assets', {\n  headers: { Authorization: 'Bearer pm_demo_stellar' }\n});\nconst { data } = await response.json();\nconsole.log(data);`;const python=`# Python · demo only\nimport requests\nresponse = requests.get(\n  'http://127.0.0.1:8080/openapi/v1/assets',\n  headers={'Authorization': 'Bearer pm_demo_stellar'}, timeout=10\n)\nprint(response.json())`;const java=`// Java / OpenFeign (内部服务通信，不用于外部 API 鉴权)\n// 外部调用方使用 HTTPS REST + API Key。\n// Peach Cloud 内部微服务间使用 OpenFeign。`;return `${banner()}<div class="portal-grid two">${box('JavaScript',code(snippet))}${box('Python',code(python))}${box('Java 服务端说明',code(java))}${box('安全与错误处理',`<div class="portal-list">${['不要在浏览器中暴露 Secret API Key','任务必须通过状态查询或 Webhook 确认','对 429/5xx 实施有界退避','所有写入请求设置幂等标识','租户身份由服务端根据 Key 解析'].map(x=>`<div class="portal-list-row">${x}</div>`).join('')}</div>`)}</div>`;}
function activityTable(limit){const rows=(activity.items||[]).slice(0,limit);return rows.length?`<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>类型</th><th>活动描述</th><th>时间</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="pill blue">${esc(x.category)}</span></td><td>${esc(x.detail)}</td><td>${new Date(x.createdAt).toLocaleString('zh-CN')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="portal-empty"><strong>暂无外部调用</strong>在 Open API 调试器执行一次完整流程，活动就会显示在这里。</div>';}
function activityPage(){return `${banner()}<div class="portal-toolbar"><span>来自本地 Mock HTTP API 的真实请求日志摘要</span>${button('刷新活动','refresh','primary')}</div>${box('请求与业务活动',activityTable(20))}`;}
function usagePage(){return `${banner()}<div class="portal-grid">${metric('接口请求量',fmt(activity.totalCalls),'包含成功和拒绝的授权请求')}${metric('已完成上传会话',fmt(activity.assets?.length),'本地 Mock API 创建的资产')}${metric('模拟 Job 数量',fmt(activity.jobs?.length),'所有 Job 仍为模拟队列状态')}</div><div class="portal-panel">${box('跨入口联动说明',`<div class="portal-list-row"><span>在开发者平台生成一个 API Key，然后进入独立 Open API 服务使用它发起请求。请求执行后，企业控制台首页的“开放 API 联动”卡片将显示新增活动。</span></div><div style="margin-top:15px"><a class="portal-button primary" href="../openapi/index.html">前往 Open API 调试器 ↗</a></div>`)}</div>`;}
function render(){view=(location.hash||'#overview').slice(1);if(!panels[view])view='overview';document.title=`${panels[view][0]} · Peach Media Developers`;
  const left=`<aside class="portal-sidebar"><a class="entry-brand" href="../index.html"><span class="brand-peach">◉</span><span>Peach Media<small>DEVELOPER CONSOLE</small></span></a><nav class="portal-nav" aria-label="开发者平台导航"><h4>INTEGRATION</h4>${nav.map(([id,icon])=>`<a href="#${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}><span>${icon}</span>${panels[id][0]}</a>`).join('')}</nav><div class="portal-footer">API-first · Local demo only</div></aside>`;
  const right=`<div class="portal-content"><header class="portal-topbar"><span class="top-title">开发者平台 / <b>${panels[view][0]}</b></span><nav aria-label="其他产品入口"><select class="portal-select" id="dev-tenant" aria-label="演示租户">${tenants.map(t=>`<option value="${t.id}" ${t.id===tenantId?'selected':''}>${esc(t.name)}</option>`).join('')}</select><a class="portal-link" href="../console/index.html">企业控制台 ↗</a><a class="portal-link" href="../openapi/index.html">Open API ↗</a></nav></header><main id="dev-main" class="portal-main"><span class="portal-eyebrow">PEACH MEDIA / DEVELOPERS</span><h1 class="portal-title">${panels[view][0]}</h1><p class="portal-subtitle">${panels[view][1]}　${status()}</p>${({overview:dashboard,projects:projectPage,credentials:credentialPage,webhooks:webhookPage,docs:docsPage,sdk:sdkPage,activity:activityPage,usage:usagePage})[view]()}</main></div>`;
  document.getElementById('developer-root').innerHTML=`<div class="portal-shell">${left}${right}</div>`;
  renderDialog();}
function renderDialog(){let root=document.getElementById('dev-dialog');if(!root){root=document.createElement('div');root.id='dev-dialog';document.body.appendChild(root);}if(!dialog){root.innerHTML='';return;}
  let content='';if(dialog==='project')content=`<form id="create-project" class="portal-form" novalidate><label>应用名称<input name="name" class="portal-input" required maxlength="64" placeholder="电商素材服务"></label><label>部署环境<select name="env" class="portal-select"><option>Development</option><option>Staging</option><option selected>Production</option></select></label><div class="portal-form-actions">${button('取消','close-modal') }<button class="portal-button primary" type="submit">创建应用</button></div></form>`;
  if(dialog==='credential')content=`<form id="create-credential" class="portal-form" novalidate><label>Key 名称<input name="name" class="portal-input" maxlength="64" required placeholder="生产环境服务端凭证"></label><label>API 授权范围</label><div class="scope-grid">${['assets:read','uploads:write','jobs:create','jobs:read','events:write','usage:read'].map(s=>`<label><input type="checkbox" name="scope" value="${s}" ${['assets:read','uploads:write','jobs:create','jobs:read'].includes(s)?'checked':''}>${s}</label>`).join('')}</div><div class="portal-form-actions">${button('取消','close-modal')}<button class="portal-button primary" type="submit">生成 Key</button></div></form>`;
  if(dialog==='webhook')content=`<form id="create-webhook" class="portal-form" novalidate><label>订阅名称<input name="name" class="portal-input" required maxlength="64" placeholder="业务系统回调"></label><label>回调地址（HTTPS）<input name="url" class="portal-input" type="url" required placeholder="https://example.com/media/events"></label><label>订阅事件<select name="type" class="portal-select"><option>asset.published</option><option>job.succeeded</option><option>job.failed</option></select></label><div class="portal-form-actions">${button('取消','close-modal')}<button class="portal-button primary" type="submit">创建订阅</button></div></form>`;
  if(dialog?.secret)content=`<p class="portal-alert">该演示密钥仅显示一次，不会保存在本地浏览器。请复制后用于 Open API 调试器。</p><pre class="portal-code" id="secret-preview">${esc(dialog.secret)}</pre><div class="portal-form-actions">${button('复制演示密钥','copy-secret','primary')}${button('关闭','close-modal')}</div>`;
  root.innerHTML=`<div class="portal-modal-backdrop" data-action="close-backdrop"><div class="portal-modal" role="dialog" aria-modal="true" aria-label="${dialog.secret?'演示凭证':dialog==='credential'?'生成 API Key':dialog==='project'?'创建接入应用':'创建回调订阅'}"><h2>${dialog.secret?'一次性演示密钥':dialog==='credential'?'创建 API Key':dialog==='project'?'创建接入应用':'创建 Webhook 订阅'}</h2>${content}</div></div>`;
  root.querySelector('input')?.focus();}
async function refresh(){if(!/^https?:$/.test(location.protocol)){live=false;connecting=false;render();return;}
  try{const h=await fetch('/openapi/v1/health',{signal:AbortSignal.timeout(2500)});const health=await h.json();live=h.ok&&health.data?.status==='DEMO_READY';}catch{live=false;}
  connecting=false;if(!live){credentials=[];activity={items:[],totalCalls:0,assets:[],jobs:[]};render();return;}
  const requestTenant=tenantId;
  try{const [k,a]=await Promise.all([fetch(`/demo/v1/credentials?tenantId=${encodeURIComponent(requestTenant)}`),fetch(`/demo/v1/activity?tenantId=${encodeURIComponent(requestTenant)}`)]);
    if(!k.ok||!a.ok)throw Error('无法获取演示 API 数据');const kr=await k.json(),ar=await a.json();if(requestTenant!==tenantId)return;credentials=kr.data;activity=ar.data;
  }catch(e){saveToast('无法刷新演示数据：'+e.message);}render();}
async function revoke(id){if(!live)return saveToast('请先启动本地 Mock API');if(!window.confirm('确认撤销此演示 API Key？撤销后不能恢复。'))return;const r=await fetch(`/demo/v1/credentials/${encodeURIComponent(id)}:revoke?tenantId=${encodeURIComponent(tenantId)}`,{method:'POST'});if(!r.ok)return saveToast('撤销失败，请重试');saveToast('演示凭证已撤销');await refresh();}
function runAction(action,id){switch(action){case 'open-project':dialog='project';renderDialog();return;case 'open-key':if(!live)return saveToast('请运行 node prototype/mock-server.cjs 后创建可调用的演示 Key');dialog='credential';renderDialog();return;case 'open-webhook':dialog='webhook';renderDialog();return;case 'close-modal':dialog=null;renderDialog();return;case 'close-backdrop':dialog=null;renderDialog();return;case 'refresh':refresh();return;case 'goto-docs':location.hash='docs';return;case 'revoke-key':revoke(id);return;case 'copy-secret':{const secret=dialog?.secret;if(!secret)return;const promise=navigator.clipboard?.writeText(secret);if(promise?.then)promise.then(()=>saveToast('已复制演示密钥')).catch(()=>saveToast('请手动复制密钥'));else saveToast('请手动复制密钥');return;}case 'test-webhook':saveToast('已模拟回调投递；未向外部 URL 发送请求');return;}}
async function onForm(form){const f=new FormData(form),name=String(f.get('name')||'').trim();if(!name){saveToast('请填写名称');form.querySelector('[name=name]')?.focus();return;}
  if(form.id==='create-project'){projects.push({id:'demo_pr_'+Date.now(),tenantId,name,env:f.get('env')});persist();dialog=null;render();saveToast('已创建浏览器内的演示接入应用');return;}
  if(form.id==='create-webhook'){let url;try{url=new URL(String(f.get('url')||''));}catch{return saveToast('请输入有效的 HTTPS 回调地址');}if(url.protocol!=='https:')return saveToast('回调地址必须为 HTTPS');webhooks.push({id:'demo_wh_'+Date.now(),tenantId,name,url:url.href,type:f.get('type')});persist();dialog=null;render();saveToast('已创建模拟回调订阅');return;}
  if(form.id==='create-credential'){const scopes=f.getAll('scope');if(!scopes.length)return saveToast('请至少选择一个 Scope');if(working)return;working=true;try{const r=await fetch('/demo/v1/credentials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tenantId,name,scopes})});const body=await r.json();if(!r.ok)throw Error(body.message||'密钥创建失败');dialog={secret:body.data.secret};await refresh();renderDialog();saveToast('演示 API Key 已生成，请保存');}catch(e){saveToast(e.message);}finally{working=false;}return;}}
window.addEventListener('hashchange',()=>{dialog=null;render();refresh();});
document.addEventListener('click',e=>{const x=e.target.closest('[data-action]');if(!x)return;if(x.dataset.action==='close-backdrop'&&e.target!==x)return;runAction(x.dataset.action,x.dataset.id);});
document.addEventListener('change',e=>{if(e.target.id==='dev-tenant'){tenantId=e.target.value;persist();refresh();}});
document.addEventListener('submit',e=>{if(['create-project','create-webhook','create-credential'].includes(e.target.id)){e.preventDefault();onForm(e.target);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){dialog=null;renderDialog();}});
render();refresh();
})();
